class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def getMaxSum(root):
    def dfs(node):
        if not node:
            return (0, 0)
        left_with, left_without = dfs(node.left)
        right_with, right_without = dfs(node.right)
        with_node = node.val + left_without + right_without
        without_node = max(left_with, left_without) + max(right_with, right_without)
        return (with_node, without_node)

    return max(dfs(root))

import sys
from collections import deque

def build_tree(index, nodes):
    if index >= len(nodes) or nodes[index] is None:
        return None
    node = TreeNode(nodes[index])
    node.left = build_tree(2 * index + 1, nodes)
    node.right = build_tree(2 * index + 2, nodes)
    return node

input = sys.stdin.read().strip()
values = list(map(int, input.split()))
root = build_tree(0, values)
print(getMaxSum(root))
